#pragma once

// ATen/core/aten_interned_strings.h — SonicBoom M1 hand-authored minimal
// header.
//
// Upstream this file is generated by torchgen from
// aten/src/ATen/templates/aten_interned_strings.h, substituting every ATen
// operator name into FORALL_ATEN_BASE_SYMBOLS (and every attribute into
// FORALL_ATTR_BASE_SYMBOLS). Those macros are then inlined into
// FORALL_NS_SYMBOLS (interned_strings.h) to precompute the c10::Symbol enum
// for every operator.
//
// The dispatcher core (schema / OperatorName / IValue / boxing) addresses
// operators by string OperatorName, not by interned c10::Symbol, so the
// precomputed aten symbol table is not load-bearing for v0 dispatch. SonicBoom
// therefore materializes only the minimal proof-set + compile-closure symbols
// here (manifest M1) instead of the full operator universe.

#include <torch/headeronly/macros/Macros.h>

#if defined(TORCH_ASSERT_NO_OPERATORS) || \
    defined(TORCH_ASSERT_ONLY_METHOD_OPERATORS)
#error \
    "Do not include ATen/core/aten_interned_strings.h when TORCH_ASSERT_NO_OPERATORS or TORCH_ASSERT_ONLY_METHOD_OPERATORS is defined"
#endif

// ATen symbols correspond exactly to operators defined in ATen. The v0 list is
// the M1 proof set (contiguous, fill_, to, zero_) plus the operator methods the
// aten/core compile closure (ivalue.cpp) requires: is_nonzero, eq, lt, clone,
// indices, coalesce.
#define FORALL_ATEN_BASE_SYMBOLS(_) \
  _(aten, contiguous)               \
  _(aten, fill_)                    \
  _(aten, to)                       \
  _(aten, zero_)                    \
  _(aten, is_nonzero)               \
  _(aten, eq)                       \
  _(aten, lt)                       \
  _(aten, clone)                    \
  _(aten, indices)                  \
  _(aten, coalesce)

// Attribute symbols are JIT-graph attributes, not used by the v0 dispatcher
// core. Empty for the M1 minimal build.
#define FORALL_ATTR_BASE_SYMBOLS(_)
